langs = ["en", "fr", "es", "de"]
out = ["/**",
       " * RockTranslate — UI strings of the reader features (selection bubble, side",
       " * panel, palette, tabs...). Merged into the i18n store at startup.",
       " * Generated from one table so the 4 languages always have the same keys.",
       " */",
       "document.addEventListener('alpine:init', () => {",
       "    const strings = " + json.dumps({l: {k: v[i] for k, v in K.items()} for i, l in enumerate(langs)},
                                            ensure_ascii=False, indent=8) + ";",
       "    const store = Alpine.store('i18n');",
       "    Object.keys(strings).forEach((lang) => {",
       "        if (store.translations[lang]) Object.assign(store.translations[lang], strings[lang]);",
       "    });",
       "});", ""]
open(__import__("os").path.join(__import__("os").path.dirname(__import__("os").path.abspath(__file__)), "..", "src", "rocktranslate", "assets", "ui", "js", "reader_i18n.js"), "w", encoding="utf-8").write("\n".join(out))
print(len(K), "keys")
